#undef RULE_ACT_OR
#undef RULE_ARG_ARG_MASK
#undef RULE_ARG_KIND_MASK
#undef RULE_ARG_OFFSET
#undef RULE_ARG_OFFSET2
#undef RULE_ARG_OFFSET3
#undef RULE_ARG_OFFSET_IDS
